entries[44490] = { ["name"] = "Formel: Stiefel - Großer Sturmangriff", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch32 Stiefel dauerhaft zu verzaubern32 sodass die Angriffskraft um 32 erhöht wird. Erfordert einen Gegenstand der Stufe 32 oder höher.\nStiefel dauerhaft verzaubern, sodass die Angriffskraft um 32 erhöht wird." }
entries[44491] = { ["name"] = "Formel: Stiefel - Vitalität der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch15 Stiefel dauerhaft zu verzaubern15 sodass die Ausdauer um 15 und das Bewegungstempo geringfügig erhöht wird. Erfordert einen Gegenstand der Stufe 15 oder höher.\nStiefel dauerhaft verzaubern, sodass die Ausdauer um 15 und das Bewegungstempo um 8% erhöht werden." }
entries[44492] = { ["name"] = "Formel: Waffe - Berserker", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Angriffskraft gelegentlich auf Kosten verringerter Rüstung erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Angriffskraft gelegentlich um 400 erhöht wird, die Rüstung währenddessen jedoch verringert ist." }
entries[44493] = { ["name"] = "Waffe - Berserker", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Angriffskraft gelegentlich um 400 erhöht wird, die Rüstung währenddessen jedoch verringert ist.\nVerkaufspreis:" }
entries[44494] = { ["name"] = "Formel: Waffe - Lebenswächter", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (425)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass der Träger manchmal bei ausgeführten Nahkampfangriffen geheilt wird. Erfordert einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Ihr manchmal geheilt werdet, wenn Ihr im Nahkampf zuschlagt." }
entries[44495] = { ["name"] = "Formel: Waffe - Schwarze Magie", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (440)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass durch Eure Schadenszauber gelegentlich das Tempo erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Schadenszauber gelegentlich das Tempo um 250 erhöhen." }
