entries[44499] = { ["name"] = "Geborgene Dunkeleisenteile", ["text"] = "Benötigt Ingenieurskunst (450)" }
entries[44500] = { ["name"] = "Elementiumveredelter Auspuff", ["text"] = "Benötigt Ingenieurskunst (450)\n\"Limitierte Auflage\"" }
entries[44501] = { ["name"] = "Goblinmaschinenkolben", ["text"] = "Benötigt Ingenieurskunst (450)\n\"Wird von Roxi Rammrakete in K3 verkauft.\"" }
entries[44502] = { ["name"] = "Bauplan: Feuerstuhl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Feuerstuhls.\nVerkaufspreis:\nFeuerstuhl\nReittier\nBenötigt eine Horde-Rasse\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\nVerkaufspreis:\nBenötigt Titanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44503] = { ["name"] = "Bauplan: Chopper des Robogenieurs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Chopper des Robogenieurs.\nVerkaufspreis:\nChopper des Robogenieurs\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\nBenötigt Titanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44504] = { ["name"] = "Nesingwary 4000", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n590 - 1,096 Schaden Tempo 2.80\n(301.07 Schaden pro Sekunde)\n+125 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 67.\n\nGelber Sockel\nSockelbonus: + 8 Angriffskraft\n\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nVerkaufspreis:" }
entries[44505] = { ["name"] = "Staubbringer", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Dolch\n235 - 437 Schaden Tempo 1.80\n(186.67 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 78\nTrefferchance: Überzieht den Feind mit 80 Feuerschaden.\n\"Klinge des Purpurroten Hausherren.\"\nVerkaufspreis:" }
entries[44506] = { ["name"] = "Automat für Saronitpfeile", ["text"] = "Verkaufspreis:" }
entries[44507] = { ["name"] = "Ultrasichere Kugelmaschine", ["text"] = "\"Verursachte Unfälle durch dieses Gerät sind um fast 17% gesunken!\"\nVerkaufspreis:" }
