entries[44793] = { ["name"] = "Foliant der Verwandlung: Hase", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Verwandlung: Hase.\nVerwandelt den Feind in einen harmlosen Hasen und zwingt ihn, 50 Sek. lang so herumzuhoppeln. Während der Gegner in einen Hasen verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[44794] = { ["name"] = "Frühlingshasenpfote", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Frühlingshasen beschwören oder wieder freigeben." }
entries[44800] = { ["name"] = "Frühlingsrobe", ["text"] = "Wird beim Aufheben gebunden\nBrust\nBenutzen: Pflanzt eine Blume. (1 Min Abklingzeit)" }
entries[44802] = { ["name"] = "Geliehener Eierkorb", ["text"] = "QuestgegenstandIn Schildhand geführt\nBenötigt Nobelgartenfest\nBenutzen: Erhöht das Tempo 10 Sek. lang um 60%. Funktioniert nur, wo während des Nobelgartenfestes bunt gefärbte Eier versteckt sind. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[44803] = { ["name"] = "Frühlingsreif", ["text"] = "Wird beim Aufheben gebunden\nKopf\n43 Rüstung\nVerkaufspreis:" }
entries[44804] = { ["name"] = "Indalamars Schwächungsverzauberung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schwächt das Ziel, erhöht den erlittenen Zauberschaden um 8%, verringert die Rüstung um 12%.\nVerkaufspreis:" }
entries[44805] = { ["name"] = "Indalamars Testtotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Summons a Stoneclaw Totem TEST.\nVerkaufspreis:" }
