entries[44807] = { ["name"] = "Indalars heilige Handgranate", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Segnet alle Ziele mit einer heiligen Machtinfusion oder verflucht sie mit dem Bann aller Schlachtzügler.\nVerkaufspreis:" }
entries[44808] = { ["name"] = "Magieerfüllte Rüstung der Horde", ["text"] = "Questgegenstand\n\"Die Essenz des Soldaten haftet an der Rüstung.\"" }
entries[44809] = { ["name"] = "Kräuterbeutel der Horde", ["text"] = "Questgegenstand\n\"Duftend und zerbrechlich\"" }
