entries[44811] = { ["name"] = "Foliant der Verwandlung: Truthahn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verwandlung: Truthahn'.\nVerwandelt den Feind in einen harmlosen Truthahn und zwingt ihn, 50 Sek. lang so herumzuwandern. Während der Gegner in einen Truthahn verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren.\nVerkaufspreis:" }
entries[44812] = { ["name"] = "Truthahnbüchse", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Pilgerfreudenfest\nBenutzen: Bedeckt das Ziel mit Truthahnfedern." }
entries[44815] = { ["name"] = "Armschiene - Großer Sturmangriff", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Angriffskraft um 50 erhöht wird.\nVerkaufspreis:" }
entries[44817] = { ["name"] = "Der Unruhestifter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt ein befreundetes Ziel in ein Schaf und zwingt es, 15 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren und ausschließlich in Dalaran.\nVerkaufspreis:" }
entries[44818] = { ["name"] = "Nobelgartenei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenötigt Nobelgartenfest\nBenutzen: Platziert ein bunt gefärbtes Ei. (1 Stunde Abklingzeit)" }
entries[44819] = { ["name"] = "Blizzardbärenbaby", ["text"] = "Accountgebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um das Blizzardbärenbaby zu beschwören und freizugeben." }
