entries[44836] = { ["name"] = "Kürbiskuchen", ["text"] = "Benötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:", ["unresolvedValues"] = true }
