entries[44842] = { ["name"] = "Roter Drachenfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren roten Drachenfalken oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[44843] = { ["name"] = "Blauer Drachenfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren blauen Drachenfalken oder gibt ihn wieder frei. Das ist ein Flugreittier." }
