entries[44866] = { ["name"] = "Treues Muli", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört Euer treues Muli, was Euch für eine Dauer von 3 Min. Zugriff auf Eure in der Bank gelagerten Gegenstände ermöglicht. (12 Std. Abklingzeit)" }
entries[44867] = { ["name"] = "Packmuli", ["text"] = "Einzigartig\nBenutzen: Beschwört ein Packmuli, was Euch für die Dauer von 3 Min. Zugriff auf Eure in der Bank gelagerten Gegenstände ermöglicht. Das Muli kann nur einmal beschworen werden. (1 Min Abklingzeit)\nVerkaufspreis:" }
