entries[44869] = { ["name"] = "Zorninsigne der Wildherzen", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Tempowertung um + 71.\nBenötigt Stufe 70\nAnlegen: Ihr verfallt in Raserei, nachdem Ihr eine Kreatur getötet habt, die Erfahrung gewährt. Eure kritische Trefferchance wird für die nächsten 10 Sek. erhöht.\nVerkaufspreis:" }
entries[44870] = { ["name"] = "Orakeltalisman der Ablution", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 71.\nBenötigt Stufe 70\nAnlegen: Stellt Mana, Wut, Energie, Fokus oder Runenmacht wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt.\nVerkaufspreis:" }
